```java
import java.sql.*;

public class DatabaseManager {
    public void getUserData(String username) throws SQLException {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/db", "user", "pass");

        // Use a PreparedStatement to prevent SQL Injection.
        // The API handles the escaping of input automatically via parameterized queries.
        String sql = "SELECT * FROM users WHERE username = ?";
        PreparedStatement pstmt = conn.prepareStatement(sql);

        // The input is treated strictly as data, not as executable code.
        pstmt.setString(1, username);

        ResultSet rs = pstmt.executeQuery();
        while (rs.next()) {
            System.out.println("User found: " + rs.getString("email"));
        }
    }
}
```

